    CSoundEvent m_items[5];
    unsigned long m_count;
    CSoundEvent* Get(unsigned long index) { return &m_items[index]; }
};

struct CListener {
    CListener* m_pNext;
    int m_detached;
};

struct CEventSet {
    CListener* m_pHead;
    CListener* GetFirstListener() { return m_pHead; }
