public:
    ~PKCWorkerQueue()
    {
        {
            CScopedLock lock(&m_section);
            m_requests.insert(m_requests.end(), 0);
            m_semaphore.Release();
        }
        m_pThread->Join();
        delete m_pThread;
    }
    PKCCriticalSection m_section;
    RequestVector      m_requests;
    PKCSemaphore       m_semaphore;
    PKCThread*         m_pThread;
};

int main()
{
