        q->m_semaphore.m_count = 0;
        q->m_requests.insert(q->m_requests.end(), &pending);
        q->m_pThread = new PKCThread;
        q->m_pThread->m_pQueue = &q->m_requests;
        q->m_pThread->m_sawStop = 0;
